function extractVideoId(raw) {
  const s = String(raw || '').trim();
  if (!s) return { video_id: '', error: 'missing_url' };

  // Accept a raw video id directly.
  if (/^[A-Za-z0-9_-]{11}$/.test(s)) return { video_id: s };

  try {
    const u = new URL(s);
    const host = (u.hostname || '').toLowerCase();
    const path = u.pathname || '';

    // https://youtu.be/<id>
    if (host.includes('youtu.be')) {
      const parts = path.split('/').filter(Boolean);
      const vid = parts[0] || '';
      return { video_id: (vid || '').split('?')[0].split('&')[0] };
    }

    // https://www.youtube.com/shorts/<id>
    if (path.startsWith('/shorts/')) {
      const vid = path.split('/shorts/')[1]?.split('/')?.[0] || '';
      return { video_id: (vid || '').split('?')[0].split('&')[0] };
    }

    // https://www.youtube.com/watch?v=<id>
    const v = u.searchParams.get('v') || '';
    if (v) return { video_id: v };

    return { video_id: '', error: 'could_not_parse_video_id' };
  } catch (e) {
    return { video_id: '', error: 'invalid_url' };
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function httpJson(options) {
  try {
    const data = await this.helpers.request({ ...options, json: true });
    return { ok: true, data };
  } catch (e) {
    const statusCode = e.statusCode || e.status || null;
    const errBody = e.error || e.response?.body || null;
    return { ok: false, statusCode, error: errBody, message: e.message || String(e) };
  }
}

function pickBody(inputJson) {
  // Webhook body is usually under `body`.
  const b = (inputJson && typeof inputJson === 'object' ? (inputJson.body || inputJson) : {}) || {};
  return b;
}

function toQS(params) {
  const entries = Object.entries(params || {}).filter(([, v]) => v !== undefined && v !== null && String(v).trim() !== '');
  if (!entries.length) return '';
  return '?' + entries.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join('&');
}

const body = pickBody($json);
const input = body.url || body.youtube_url || body.video_url || body.video_id;
const voice_provider = body.voice_provider;
const voice_id = body.voice_id;

const parsed = extractVideoId(input);
const video_id = parsed.video_id;
if (!video_id) {
  return [{ json: { status: 'failed', step: 'parse_video_id', error: parsed.error || 'parse_failed', input: String(input || '') } }];
}

const BASE = 'http://runner:8000';
const steps = [];

// 0) Verify voice configuration (VM truth)
{
  const r = await httpJson.call(this, { method: 'GET', uri: `${BASE}/api/verify/voice`, timeout: 30000 });
  steps.push({ step: 'verify_voice', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  if (!r.ok || !r.data || r.data.status !== 'success') {
    return [{ json: { status: 'failed', step: 'verify_voice', video_id, details: r, steps } }];
  }
}

// 1) Ingest
{
  const r = await httpJson.call(this, { method: 'POST', uri: `${BASE}/api/ingest/${video_id}`, timeout: 600000 });
  steps.push({ step: 'ingest', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  if (!r.ok || !r.data || r.data.status !== 'success') {
    return [{ json: { status: 'failed', step: 'ingest', video_id, details: r, steps } }];
  }
}

// 2) Script (retry once with force=1)
let scriptOut = null;
{
  const callScript = async (force) => {
    const qs = force ? '?force=1' : '';
    return httpJson.call(this, { method: 'POST', uri: `${BASE}/api/script/${video_id}${qs}`, timeout: 300000 });
  };

  let r = await callScript(false);
  steps.push({ step: 'script', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  if (!r.ok || !r.data || r.data.status !== 'success') {
    r = await callScript(true);
    steps.push({ step: 'script_retry', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  }

  if (!r.ok || !r.data || r.data.status !== 'success') {
    return [{ json: { status: 'failed', step: 'script', video_id, details: r, steps } }];
  }
  scriptOut = r.data;
}

// 3) Voice (retry once with force=1)
let voiceOut = null;
{
  const qsBase = toQS({ voice_provider, voice_id });
  const callVoice = async (force) => {
    const qs = toQS({ voice_provider, voice_id, force: force ? 1 : undefined });
    return httpJson.call(this, { method: 'POST', uri: `${BASE}/api/voice/${video_id}${qs}`, timeout: 600000 });
  };

  let r = await callVoice(false);
  steps.push({ step: 'voice', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  if (!r.ok || !r.data || r.data.status !== 'success') {
    r = await callVoice(true);
    steps.push({ step: 'voice_retry', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  }

  if (!r.ok || !r.data || r.data.status !== 'success') {
    return [{ json: { status: 'failed', step: 'voice', video_id, details: r, steps } }];
  }
  voiceOut = r.data;
}

// 4) Render (retry once)
let renderOut = null;
{
  const callRender = async () => {
    return httpJson.call(this, { method: 'POST', uri: `${BASE}/api/render/${video_id}`, timeout: 1800000 });
  };

  let r = await callRender();
  steps.push({ step: 'render', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });

  if (!r.ok || !r.data || r.data.status !== 'success') {
    await sleep(5000);
    r = await callRender();
    steps.push({ step: 'render_retry', ok: r.ok, statusCode: r.statusCode, data: r.data, error: r.error, message: r.message });
  }

  if (!r.ok || !r.data || r.data.status !== 'success') {
    return [{ json: { status: 'failed', step: 'render', video_id, details: r, steps } }];
  }
  renderOut = r.data;
}

const output_url = (renderOut && renderOut.output_url) || `/api/media/output/${video_id}/final_video.mp4`;

return [
  {
    json: {
      status: 'success',
      video_id,
      input_url: String(input || ''),
      output_url,
      source_url: `http://localhost:8000/api/media/videos/${video_id}/${video_id}.mp4`,
      final_url: `http://localhost:8000${output_url}`,
      download_url: `http://localhost:8000${output_url}`,
      narration_url: voiceOut?.narration_url ? `http://localhost:8000${voiceOut.narration_url}` : null,
      narration_normalized_url: voiceOut?.narration_normalized_url ? `http://localhost:8000${voiceOut.narration_normalized_url}` : null,
      no_english_bleed: renderOut?.no_english_bleed || null,
      script_quality_score: scriptOut?.quality_score || null,
      steps
    }
  }
];
